    constructor(C _c) { c = _c; }

    function run(address logger, bool status, address _keepAddress) public {
        c.setApprovedLogger(logger, status);
        bool beforeApproved = c.approvedToLog(_keepAddress);
        bool r1 = c.logCreated(_keepAddress);
        bool r2 = c.logRedemptionRequested(_keepAddress, bytes32(0), 1, new bytes(0), 0, new bytes(0));
        bool r3 = c.logGotRedemptionSignature(bytes32(0), bytes32(0), bytes32(0));
        bool r4 = c.logRegisteredPubkey(bytes32(0), bytes32(0));
        bool r5 = c.logSetupFailed();
        bool r6 = c.logFraudDuringSetup();
        bool r7 = c.logFunded();
        bool r8 = c.logCourtesyCalled();
        bool r9 = c.logStartedLiquidation(false);
        bool r10 = c.logRedeemed(bytes32(0));
        bool r11 = c.logLiquidated();
        bool r12 = c.logExitedCourtesyCall();
