        bool rFraud = c.logFraudDuringSetup();
        bool rFunded = c.logFunded();
        bool rCourtesy = c.logCourtesyCalled();
        bool rLiquidation = c.logStartedLiquidation(wasFraud);
        bool rRedeemed = c.logRedeemed(txid);
        bool rLiquidated = c.logLiquidated();
        bool rExited = c.logExitedCourtesyCall();

        assert(
            loggerFlag == enable &&
            rCreate == enable &&
            rRedeemReq == enable &&
            rSig == enable &&
            rPubkey == enable &&
            rSetupFailed == enable &&
            rFraud == enable &&
            rFunded == enable &&
            rCourtesy == enable &&
            rLiquidation == enable &&
            rRedeemed == enable &&
            rLiquidated == enable &&
            rExited == enable
        );
    }
}

