        // 6. logFraudDuringSetup
        reverted = false;
        try c.logFraudDuringSetup() { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 7. logFunded
        reverted = false;
        try c.logFunded() { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 8. logCourtesyCalled
        reverted = false;
        try c.logCourtesyCalled() { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 9. logStartedLiquidation
        reverted = false;
        try c.logStartedLiquidation(wasFraud) { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 10. logRedeemed
        reverted = false;
        try c.logRedeemed(txid) { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 11. logLiquidated
        reverted = false;
        try c.logLiquidated() { reverted = false; } catch { reverted = true; }
        assert(!reverted && !c.approvedToLog(loggerForCall));

        // 12. logExitedCourtesyCall
