contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool wasFraud, bytes32 txid) public {
        bool ok;
        bool reverted;

        // Ensure the caller (this test contract) is not an approved logger.
        require(!c.approvedToLog(address(this)));

        // logCreated
        ok = c.logCreated(address(this));
        assert(ok == false);

        // logRedemptionRequested
        ok = c.logRedemptionRequested(address(this), txid, 1, "", 0, "");
        assert(ok == false);

        // logGotRedemptionSignature
        ok = c.logGotRedemptionSignature(txid, txid, txid);
        assert(ok == false);

        // logRegisteredPubkey
        ok = c.logRegisteredPubkey(txid, txid);
        assert(ok == false);

        // logSetupFailed
        ok = c.logSetupFailed();
        assert(ok == false);

        // logFraudDuringSetup
        ok = c.logFraudDuringSetup();
        assert(ok == false);

        // logFunded
        ok = c.logFunded();
        assert(ok == false);

        // logCourtesyCalled
        ok = c.logCourtesyCalled();
        assert(ok == false);

        // logStartedLiquidation
        ok = c.logStartedLiquidation(wasFraud);
        assert(ok == false);

        // logRedeemed
        ok = c.logRedeemed(txid);
        assert(ok == false);

        // logLiquidated
        ok = c.logLiquidated();
        assert(ok == false);

        // logExitedCourtesyCall
        ok = c.logExitedCourtesyCall();
        assert(ok == false);

        // General rule: unapproved caller cannot log, remains unapproved, and no Ether is moved.
        assert(!c.approvedToLog(address(this)) && address(c).balance == 0);
    }

    receive() external payable {}
}

