contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool approvedBefore, bool wasFraud) public payable {
        require(msg.sender != address(0));
        require(!approvedBefore);

        bool callerApprovedBefore = c.approvedToLog(address(this));

        bool retFunded = c.logFunded();
        bool retCourtesy = c.logCourtesyCalled();
        bool retStartedLiq = c.logStartedLiquidation(wasFraud);
        bool retExited = c.logExitedCourtesyCall();

        bool callerApprovedAfter = c.approvedToLog(address(this));

        assert(!retFunded && !retCourtesy && !retStartedLiq && !retExited && !callerApprovedAfter);
    }

    receive() external payable {}
}
